declare(strict_types=1);

namespace Doctrine\Persistence\Mapping\Driver;

use Doctrine\Persistence\Mapping\ClassMetadata;

use function array_filter;
use function array_values;
use function method_exists;

/**
 * The StaticPHPDriver calls a static loadMetadata() method on your entity
 * classes where you can manually populate the ClassMetadata instance.
 */
class StaticPHPDriver implements MappingDriver
{
    /** Locator used to discover the class names handled by this driver. */
    private readonly ClassLocator $locator;

    /**
     * Whether transient classes should be filtered out of {@see getAllClassNames()}.
     *
     * Filtering only applies when the driver scans file system paths; a class
     * locator provided explicitly is trusted to list the relevant classes.
     */
    private readonly bool $filterTransient;

    /**
     * Cache for {@see getAllClassNames()}.
     *
     * @var array<int, string>|null
     * @phpstan-var list<class-string>|null
     */
    private array|null $classNames = null;

    /** @param array<int, string>|ClassLocator $paths */
    public function __construct(array|ClassLocator $paths)
    {
        if ($paths instanceof ClassLocator) {
            $this->locator         = $paths;
            $this->filterTransient = false;
        } else {
            $this->locator         = FileClassLocator::createFromDirectories($paths);
            $this->filterTransient = true;
        }
    }

    public function loadMetadataForClass(string $className, ClassMetadata $metadata): void
    {
        $className::loadMetadata($metadata);
    }

    /**
     * {@inheritDoc}
     */
    public function getAllClassNames(): array
    {
        if ($this->classNames !== null) {
            return $this->classNames;
        }

        $classNames = $this->locator->getClassNames();

        if ($this->filterTransient) {
            $classNames = array_values(array_filter(
                $classNames,
                fn (string $className): bool => ! $this->isTransient($className),
            ));
        }

        return $this->classNames = $classNames;
    }

    public function isTransient(string $className): bool
    {
        return ! method_exists($className, 'loadMetadata');
